Gestión de esquemas segura.ejemplo:
-- Aislamiento por esquema y restricción de integridad en PostgreSQL
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
CREATE SCHEMA IF NOT EXISTS pii;
REVOKE ALL ON SCHEMA pii FROM PUBLIC;
CREATE TABLE pii.identidades (
  user_id BIGINT PRIMARY KEY REFERENCES core.users(id),
  balance NUMERIC(12,2) NOT NULL CHECK (balance >= 0)
);

Migraciones seguras.ejemplo:
-- Migración segura con lock_timeout y creación concurrente de índice
SET lock_timeout = '2s';
SET statement_timeout = '30s';
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_orders_tenant
  ON core.orders (tenant_id, created_at);

Prepared statement.ejemplo:
// PHP PDO con prepared statements reales (sin emulación)
$pdo->setAttribute(PDO::ATTR_EMULATE_PREPARES, false);
$stmt = $pdo->prepare('SELECT id, email FROM users WHERE org_id = :org AND status = :st');
$stmt->execute(['org' => $orgId, 'st' => 'active']);

Retención de datos.ejemplo:
-- Índice TTL nativo en MongoDB para expirar sesiones automáticamente a los 7 días
db.sessions.createIndex({ "createdAt": 1 }, { expireAfterSeconds: 604800 });

-- En PostgreSQL particionado: borrado instantáneo sin vacuum masivo
DROP TABLE IF EXISTS audit_logs_2025_01;

Transparent data encryption (TDE).ejemplo:
-- Habilitación de TDE en SQL Server con jerarquía de claves
USE master;
CREATE MASTER KEY ENCRYPTION BY PASSWORD = '<Fuerte_Desde_KMS>';
CREATE CERTIFICATE TDE_Cert WITH SUBJECT = 'Prod TDE';
USE ProdDB;
CREATE DATABASE ENCRYPTION KEY WITH ALGORITHM = AES_256 ENCRYPTION BY SERVER CERTIFICATE TDE_Cert;
ALTER DATABASE ProdDB SET ENCRYPTION ON;

Usuario de base de datos con menos privi.ejemplo:
-- Cuenta de runtime con mínimo privilegio en PostgreSQL
REVOKE ALL ON SCHEMA public FROM PUBLIC;
CREATE ROLE svc_checkout LOGIN PASSWORD '<from_vault>';
GRANT USAGE ON SCHEMA core TO svc_checkout;
GRANT SELECT, INSERT, UPDATE ON core.orders, core.order_items TO svc_checkout;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA core TO svc_checkout;
